Hypothesis A12 : getr R 12%bv = Z_to_bv 64 (fb + 16).
Hypothesis CPRE : PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M fb p X s str sm en k e cat.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis POK : PECS.payload_ok p.
Hypothesis MP : PECS.mp_run tt p X.
Hypothesis NB : s_bad (r_begin p true X) = false.
Hypothesis HB : PESK.sp_hb P (s_hi (r_begin p true X)).
Hypothesis CRED : PMSP.credit_le (PEC.pot_all L P s en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model)
            (s' : PM.pst) (sm' : PM.strm) (en' : PEC.enc) (k' : PESK.sink) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M' fb p (r_begin p true X) s' str sm' en' k' e' cat ->
        PMSP.src_step (PM.p_src s) (PM.p_src s') sm sm' -> (e = true -> e' = true) ->
        L5C.hpres L LBX sp (PMSP.pm_scr 7) (PEC.W_crun CAD EE fb) M M' ->
        PMSP.credit_keep cr cr' (PEC.pot_all L P s en k) (PEC.pot_all L P s' en' k') ->
        model_but_vm model model' -> hi_heap HI (PEC.owned s' en' k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

