Lemma csrc_after (Wx : list L5.range) (c : Z) fxi Ri Mi mdi cri si smi eni ki ei Y fx2 R2 M2 src2 sm2 :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_more Y = true -> s_done Y = false ->
  (forall a, PMK.inW Wx a -> sp - 112 <= a < sp - 64) ->
  regs_preserved Ri R2 ->
  PM.parser_at RSEGS CAD PMSP.T3 PMSP.T4 M2 (fb + 48) (fb + 520)
     (PM.PST (PM.p_more si) (PM.p_done si) (PM.p_depth si) src2 (PM.p_tb si) (PM.p_tg si) (PM.p_b si) (PM.p_k si) (PM.p_stk si)) ->
  PM.iss_at RSEGS CAD PMSP.T3 M2 (fb + 520) str sm2 ->
  PMSP.src_step (PM.p_src si) src2 smi sm2 ->
  PECS.cwin RSEGS M2 p src2 sm2 ->
  PMSP.consumed (PM.p_src si) src2 smi sm2 = c ->
  L5C.hpres L (PEC.owned si eni ki ++ LBX) (sp - 112) 20480 (PMSP.W_src CAD fb (PM.p_src si) ++ Wx) Mi M2 ->
  hi_heap HI (PEC.owned si eni ki ++ LBX) cri M2 (m_vmmaps mdi) ->
  mid fx2 R2 M2 mdi cri (PM.PST (PM.p_more si) (PM.p_done si) (PM.p_depth si) src2 (PM.p_tb si) (PM.p_tg si) (PM.p_b si) (PM.p_k si) (PM.p_stk si)) sm2 eni ki ei
      (w_pos (s_pos Y + c) Y)
  /\ s_pos Y + c = PEC.pos_of p src2 sm2 /\ 0 <= PEC.pos_of p src2 sm2 <= blen p
  /\ (forall a n, sp - 112 <= a -> a + n <= sp - 64 -> (forall i, a <= i < a + n -> ~ PMK.inW Wx i) -> L5C.agree_on Mi M2 a n).
