(* [comment removed for export] *)
(* [comment removed for export] *)
Definition oblk (srci : PM.srcst) (tbi : PM.vstr) (eni : PEC.enc) (ki : PESK.sink) : list (Z * Z) :=
  PM.src_own srci ++ PM.vs_own tbi ++ PEC.enc_own eni ++ PESK.sink_own ki ++ LBX.

(* [comment removed for export] *)
Definition gworld (srci : PM.srcst) (tbi : PM.vstr) (smi : PM.strm) (eni : PEC.enc) (ki : PESK.sink) (ei : bool) (Y : st)
           (Mi Mx : word -> option byte) (mdx : Model) (crx : credit) (LBh : list (Z * Z)) : Prop :=
  saved Mx /\ L5C.stk (hl_sptop L) Mx sp 26624 /\ model_but_vm model mdx /\ PMSP.model_ok mdx
  /\ hi_heap HI LBh crx Mx (m_vmmaps mdx)
  /\ PM.iss_at RSEGS CAD PMSP.T3 Mx (fb + 520) str smi /\ PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4 Mx (fb + 440) fb eni
  /\ L5.u64_at RSEGS Mx (fb + 48 + 384) (fb + 440) /\ PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P Mx (fb + 496) ki
  /\ PMST.base_ok RSEGS CAD Mx /\ PEST.err_ok RSEGS CAD EE Mx ei /\ PEC.content_ok RSEGS CAD Mx fb p srci str smi
  /\ PEC.ec_state RSEGS CAD Mx fb (s_ec Y) cat
  /\ L5C.agree_on Mi Mx (fb + 48) 360 /\ PMPK.dkr Mi Mx (fb + 48) 384 /\ PMPK.dkr Mi Mx (PM.sr_qc srci) PM.CHUNK
  /\ (forall c n q, tbi = PM.VLong c n q -> PMPK.dkr Mi Mx q c)
  /\ incl (oblk srci tbi eni ki) LBh
  /\ (PM.sr_qc srci <= PM.sr_de srci /\ 0 <= PM.sr_rem srci /\ PM.sr_de srci + PM.sr_rem srci <= PM.sr_qc srci + PM.CHUNK)
  /\ PMK.ek L LBX sp 26624 (PEC.W_crun CAD EE fb) M Mx /\ PMK.dk L LBX sp 26624 M Mx.

Lemma gworld_of_mid fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y ->
  gworld srci tbi smi eni ki ei Y Mi Mi mdi cri (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX).
