Lemma after_gl (q : Z) (obj_unused : unit) (m : pmode) (ty : Z) (Xg : st) fx4 R4 M4 md4 cr4 si4 sm4 e4 :
  (q = 0x39ed0 \/ (q = 0x39e64 /\ getr R4 (PMK.reg 20) = Z_to_bv 64 1)) ->
  PECS.gl_ret p Xg R4 -> mid fx4 R4 M4 md4 cr4 si4 sm4 en k e4 (PECS.gl_post p Xg) ->
  getr R4 (PMK.reg 19) = Z_to_bv 64 (fb + 48 + 24) ->
  s_more Xg = true -> s_done Xg = false -> 0 <= s_pos Xg <= blen p -> s_ec Xg = s_ec X -> s_stk Xg = s_stk X -> s_estk Xg = s_estk X ->
  s_edepth Xg = s_edepth X -> s_lo Xg = s_lo X -> s_hi Xg = s_hi X -> s_bad Xg = s_bad X ->
  r_begin p true X = r_counted p m ty 0 Xg ->
  (* [comment removed for export] *)
  (forall n pos1, get_length p (s_pos Xg) = Some (n, pos1) -> s_ec X = false -> 0 <= n <= 16777216 ->
     getr R4 (PMK.reg 10) = Z_to_bv 64 n ->
     r_begin p true X = w_more true (e_begin_len 0 n (w_stk (PS m n ty 0 :: s_stk Xg) (w_pos pos1 Xg))) ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 q M4 md4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 q M4 md4) K.
Proof.
